from pathlib import Path
root=Path(__file__).resolve().parents[1]
lines=['import Bridge.CertificateData','import Mathlib.Tactic.NormNum','import Mathlib.Tactic.Ring','import Mathlib.Data.Real.Basic','', 'namespace LiebBridge.Certificate','set_option maxRecDepth 1000000','set_option maxHeartbeats 0','', 'theorem partitions14_length : partitions14.length = 135 := by decide +kernel','']
for i in range(1,21):
 lines += [f'theorem witness{i:02d}_computed :',f'    (partitions14.all fun nu => computedCoeff witness{i:02d} nu == storedCoeff witness{i:02d} nu) = true := by','  decide +kernel','']
lines += ['theorem rowsComputedCheck :','    (rows.all fun w => partitions14.all fun nu => computedCoeff w nu == storedCoeff w nu) = true := by','  simp only [rows, List.all_cons, List.all_nil, '+', '.join(f'witness{i:02d}_computed' for i in range(1,21))+', Bool.and_self]','', 'theorem computedCoeff_eq_storedCoeff (w : Witness) (hw : w ∈ rows)', '    (nu : Shape) (hnu : nu ∈ partitions14) : computedCoeff w nu = storedCoeff w nu := by', '  have h := List.all_eq_true.mp (List.all_eq_true.mp rowsComputedCheck w hw) nu hnu', '  simpa using h','', 'theorem weightsPositiveCheck : (rows.all fun w => decide (0 < w.weight)) = true := by', '  decide +kernel','', 'theorem weightsPositive (w : Witness) (hw : w ∈ rows) : 0 < w.weight := by', '  exact of_decide_eq_true (List.all_eq_true.mp weightsPositiveCheck w hw)','', 'theorem degree_4433 : hookDegree [4, 4, 3, 3] = 12012 := by decide +kernel','theorem degree_653 : hookDegree [6, 5, 3] = 15015 := by decide +kernel','theorem degree_644 : hookDegree [6, 4, 4] = 9009 := by decide +kernel','theorem degree_554 : hookDegree [5, 5, 4] = 6006 := by decide +kernel','theorem degree_5333 : hookDegree [5, 3, 3, 3] = 15015 := by decide +kernel','', 'end LiebBridge.Certificate','']
(root/'Bridge/CertificateChecks.lean').write_text('\n'.join(lines))
